alter table public.free_choice_availability_access drop constraint free_choice_availability_access_pkey;
alter table public.free_choice_availability_access add column id uuid not null default gen_random_uuid();
alter table public.free_choice_availability_access add column tattoo_case_id uuid;
alter table public.free_choice_availability_access add constraint free_choice_availability_access_pkey primary key(id);
alter table public.free_choice_availability_access add constraint free_choice_access_case_tenant_fk foreign key(tattoo_case_id,studio_id) references public.tattoo_case(id,studio_id) on delete restrict;
create unique index free_choice_access_case_unique on public.free_choice_availability_access(tattoo_case_id) where tattoo_case_id is not null;
create unique index free_choice_access_legacy_artist_unique on public.free_choice_availability_access(artist_profile_id) where tattoo_case_id is null;

create or replace function public.rotate_free_choice_availability_access(p_studio_id uuid,p_owner_user_id uuid,p_artist_profile_id uuid,p_token_hash text,p_range_start timestamptz,p_range_end timestamptz,p_duration_minutes integer,p_expires_at timestamptz,p_now timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$declare v_compatible boolean;begin
 if p_token_hash !~ '^[0-9a-f]{64}$' or p_range_start<p_now or p_range_end<=p_range_start or p_range_end>p_range_start+interval '31 days' or p_duration_minutes not between 15 and 480 or p_expires_at<=p_now or p_expires_at>p_range_end then raise exception 'invalid free-choice access' using errcode='22023';end if;perform private.assert_studio_owner(p_studio_id,p_owner_user_id);
 select exists(select 1 from public.artist_profile a join public.artist_availability_rule r on r.artist_profile_id=a.id and r.studio_id=a.studio_id join public.artist_calendar_assignment ca on ca.artist_profile_id=a.id and ca.studio_id=a.studio_id and ca.access_role in('writer','owner') join public.google_calendar_connection c on c.id=ca.connection_id and c.studio_id=a.studio_id and c.status='ACTIVE' and c.refresh_token_ciphertext is not null and c.granted_scopes @> array['https://www.googleapis.com/auth/calendar.events.freebusy']::text[] where a.id=p_artist_profile_id and a.studio_id=p_studio_id) into v_compatible;if not v_compatible then raise exception 'free-choice context not found' using errcode='P0002';end if;
 update public.free_choice_availability_access set token_hash=decode(p_token_hash,'hex'),range_start=p_range_start,range_end=p_range_end,duration_minutes=p_duration_minutes,expires_at=p_expires_at,issued_at=p_now,updated_at=p_now where artist_profile_id=p_artist_profile_id and studio_id=p_studio_id and tattoo_case_id is null;
 if not found then insert into public.free_choice_availability_access(artist_profile_id,studio_id,token_hash,range_start,range_end,duration_minutes,expires_at,issued_at,updated_at) values(p_artist_profile_id,p_studio_id,decode(p_token_hash,'hex'),p_range_start,p_range_end,p_duration_minutes,p_expires_at,p_now,p_now);end if;return jsonb_build_object('expires_at',p_expires_at);
end $$;

create type public.free_choice_request_status as enum('PENDING_OWNER_APPROVAL','EXPIRED');
create table public.free_choice_pending_request(
  id uuid primary key default gen_random_uuid(),access_id uuid not null unique references public.free_choice_availability_access(id) on delete restrict,
  studio_id uuid not null,tattoo_case_id uuid not null,artist_profile_id uuid not null,selector_hash bytea not null,
  start_at timestamptz not null,end_at timestamptz not null,expires_at timestamptz not null,status public.free_choice_request_status not null default 'PENDING_OWNER_APPROVAL',created_at timestamptz not null,
  constraint free_choice_request_selector_length check(octet_length(selector_hash)=32),constraint free_choice_request_interval check(start_at<end_at),constraint free_choice_request_expiry check(created_at<expires_at and expires_at<=start_at),
  constraint free_choice_request_case_fk foreign key(tattoo_case_id,studio_id) references public.tattoo_case(id,studio_id) on delete restrict,
  constraint free_choice_request_artist_fk foreign key(artist_profile_id,studio_id) references public.artist_profile(id,studio_id) on delete restrict
);
create index free_choice_request_active_hold_idx on public.free_choice_pending_request(studio_id,artist_profile_id,start_at,end_at) where status='PENDING_OWNER_APPROVAL';
alter table public.free_choice_pending_request enable row level security;
revoke all on table public.free_choice_pending_request from public,anon,authenticated,service_role;

create function public.rotate_free_choice_availability_access(p_studio_id uuid,p_owner_user_id uuid,p_tattoo_case_id uuid,p_artist_profile_id uuid,p_token_hash text,p_range_start timestamptz,p_range_end timestamptz,p_duration_minutes integer,p_expires_at timestamptz,p_now timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_compatible boolean;
begin
 if p_studio_id is null or p_owner_user_id is null or p_tattoo_case_id is null or p_artist_profile_id is null or p_token_hash !~ '^[0-9a-f]{64}$' or p_range_start<p_now or p_range_end<=p_range_start or p_range_end>p_range_start+interval '31 days' or p_duration_minutes not between 15 and 480 or p_expires_at<=p_now or p_expires_at>p_range_end then raise exception 'invalid free-choice access' using errcode='22023';end if;
 perform private.assert_studio_owner(p_studio_id,p_owner_user_id);
 select exists(select 1 from public.tattoo_case tattoo join public.artist_profile artist on artist.id=tattoo.artist_profile_id and artist.studio_id=tattoo.studio_id join public.artist_availability_rule rule on rule.artist_profile_id=artist.id and rule.studio_id=artist.studio_id join public.artist_calendar_assignment assignment on assignment.artist_profile_id=artist.id and assignment.studio_id=artist.studio_id and assignment.access_role in('writer','owner') join public.google_calendar_connection connection on connection.id=assignment.connection_id and connection.studio_id=artist.studio_id and connection.status='ACTIVE' and connection.refresh_token_ciphertext is not null and connection.granted_scopes @> array['https://www.googleapis.com/auth/calendar.events.freebusy']::text[] where tattoo.id=p_tattoo_case_id and tattoo.studio_id=p_studio_id and tattoo.status='OPEN' and tattoo.artist_profile_id=p_artist_profile_id) into v_compatible;
 if not v_compatible then raise exception 'free-choice context not found' using errcode='P0002';end if;
 insert into public.free_choice_availability_access(studio_id,tattoo_case_id,artist_profile_id,token_hash,range_start,range_end,duration_minutes,expires_at,issued_at,updated_at) values(p_studio_id,p_tattoo_case_id,p_artist_profile_id,decode(p_token_hash,'hex'),p_range_start,p_range_end,p_duration_minutes,p_expires_at,p_now,p_now)
 on conflict(tattoo_case_id) where tattoo_case_id is not null do update set artist_profile_id=excluded.artist_profile_id,token_hash=excluded.token_hash,range_start=excluded.range_start,range_end=excluded.range_end,duration_minutes=excluded.duration_minutes,expires_at=excluded.expires_at,issued_at=excluded.issued_at,updated_at=excluded.updated_at where free_choice_availability_access.studio_id=excluded.studio_id;
 return jsonb_build_object('expires_at',p_expires_at);
end $$;

create function public.get_free_choice_availability_management(p_studio_id uuid,p_owner_user_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 perform private.assert_studio_owner(p_studio_id,p_owner_user_id);
 return jsonb_build_object('cases',coalesce((select jsonb_agg(jsonb_build_object('id',tattoo.id,'summary',tattoo.summary,'artist_profile_id',tattoo.artist_profile_id) order by tattoo.created_at) from public.tattoo_case tattoo where tattoo.studio_id=p_studio_id and tattoo.status='OPEN' and tattoo.artist_profile_id is not null),'[]'::jsonb),'pending_requests',coalesce((select jsonb_agg(jsonb_build_object('customer_name',customer.name,'case_summary',tattoo.summary,'artist_display_name',artist.display_name,'start_at',request.start_at,'end_at',request.end_at,'expires_at',request.expires_at) order by request.created_at desc) from public.free_choice_pending_request request join public.tattoo_case tattoo on tattoo.id=request.tattoo_case_id and tattoo.studio_id=request.studio_id join public.customer customer on customer.id=tattoo.customer_id and customer.studio_id=tattoo.studio_id join public.artist_profile artist on artist.id=request.artist_profile_id and artist.studio_id=request.studio_id where request.studio_id=p_studio_id and request.status='PENDING_OWNER_APPROVAL' and request.expires_at>now()),'[]'::jsonb));
end $$;

create or replace function public.get_public_free_choice_availability_context(p_token_hash text,p_now timestamptz) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_result jsonb;begin if p_token_hash !~ '^[0-9a-f]{64}$' or p_now is null then raise exception 'invalid access' using errcode='22023';end if;
 select jsonb_build_object('range_start',access.range_start,'range_end',access.range_end,'duration_minutes',access.duration_minutes,'expires_at',access.expires_at,'case_bound',access.tattoo_case_id is not null,'artist_display_name',artist.display_name,'time_zone',rule.time_zone,'slot_increment_minutes',rule.slot_increment_minutes,'buffer_before_minutes',rule.buffer_before_minutes,'buffer_after_minutes',rule.buffer_after_minutes,'windows',coalesce((select jsonb_agg(jsonb_build_object('weekday',w.weekday,'start_time',to_char(w.start_time,'HH24:MI'),'end_time',to_char(w.end_time,'HH24:MI')) order by w.weekday,w.start_time) from public.artist_availability_window w where w.artist_profile_id=access.artist_profile_id and w.studio_id=access.studio_id),'[]'::jsonb),'calendar_id',assignment.calendar_id,'connection',jsonb_build_object('status',connection.status,'refresh_token_ciphertext',connection.refresh_token_ciphertext,'granted_scopes',connection.granted_scopes,'credential_generation',connection.credential_generation),'pending_request',(select jsonb_build_object('start_at',r.start_at,'end_at',r.end_at,'expires_at',r.expires_at) from public.free_choice_pending_request r where r.access_id=access.id and r.status='PENDING_OWNER_APPROVAL' and r.expires_at>p_now),'holds',coalesce((select jsonb_agg(jsonb_build_object('start_at',x.start_at,'end_at',x.end_at)) from (select option.start_at,option.end_at from public.booking_option option join public.booking_offer offer on offer.id=option.offer_id and offer.studio_id=option.studio_id where option.studio_id=access.studio_id and option.artist_profile_id=access.artist_profile_id and ((option.status='HELD' and offer.status='OPEN' and offer.expires_at>p_now) or(option.status='SELECTED' and offer.status='SELECTED_PENDING_CONFIRMATION' and offer.expires_at>p_now)or(option.status='CONFIRMED' and offer.status='CONFIRMED')) union all select r.start_at,r.end_at from public.free_choice_pending_request r where r.studio_id=access.studio_id and r.artist_profile_id=access.artist_profile_id and r.status='PENDING_OWNER_APPROVAL' and r.expires_at>p_now) x where x.start_at<access.range_end and x.end_at>access.range_start),'[]'::jsonb)) into v_result from public.free_choice_availability_access access join public.artist_profile artist on artist.id=access.artist_profile_id and artist.studio_id=access.studio_id join public.artist_availability_rule rule on rule.artist_profile_id=access.artist_profile_id and rule.studio_id=access.studio_id join public.artist_calendar_assignment assignment on assignment.artist_profile_id=access.artist_profile_id and assignment.studio_id=access.studio_id and assignment.access_role in('writer','owner') join public.google_calendar_connection connection on connection.id=assignment.connection_id and connection.studio_id=access.studio_id and connection.status='ACTIVE' and connection.refresh_token_ciphertext is not null and connection.granted_scopes @> array['https://www.googleapis.com/auth/calendar.events.freebusy']::text[] where access.token_hash=decode(p_token_hash,'hex') and access.expires_at>p_now;return v_result;end $$;

create function public.select_public_free_choice_availability(p_token_hash text,p_selector text,p_start_at timestamptz,p_end_at timestamptz,p_now timestamptz) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.free_choice_availability_access;r public.free_choice_pending_request;v_expiry timestamptz;begin if p_token_hash !~ '^[0-9a-f]{64}$' or p_selector !~ '^[0-9a-f]{64}$' or p_start_at<=p_now or p_end_at<=p_start_at then raise exception 'unavailable' using errcode='P0002';end if;select * into a from public.free_choice_availability_access where token_hash=decode(p_token_hash,'hex') and expires_at>p_now for update;if a.id is null or a.tattoo_case_id is null or p_start_at<a.range_start or p_end_at>a.range_end or extract(epoch from(p_end_at-p_start_at))/60<>a.duration_minutes then raise exception 'unavailable' using errcode='P0002';end if;perform pg_advisory_xact_lock(hashtextextended(a.studio_id::text||':'||a.artist_profile_id::text,0));select * into r from public.free_choice_pending_request where access_id=a.id;if r.id is not null then if r.selector_hash=decode(p_selector,'hex') and r.start_at=p_start_at and r.end_at=p_end_at and r.status='PENDING_OWNER_APPROVAL' and r.expires_at>p_now then return jsonb_build_object('start_at',r.start_at,'end_at',r.end_at,'expires_at',r.expires_at);end if;raise exception 'unavailable' using errcode='P0002';end if;if not exists(select 1 from public.tattoo_case where id=a.tattoo_case_id and studio_id=a.studio_id and status='OPEN' and artist_profile_id=a.artist_profile_id) or exists(select 1 from public.booking_option o join public.booking_offer b on b.id=o.offer_id and b.studio_id=o.studio_id where o.studio_id=a.studio_id and o.artist_profile_id=a.artist_profile_id and o.start_at<p_end_at and o.end_at>p_start_at and ((o.status='HELD' and b.status='OPEN' and b.expires_at>p_now)or(o.status='SELECTED' and b.status='SELECTED_PENDING_CONFIRMATION' and b.expires_at>p_now)or(o.status='CONFIRMED' and b.status='CONFIRMED'))) or exists(select 1 from public.free_choice_pending_request q where q.studio_id=a.studio_id and q.artist_profile_id=a.artist_profile_id and q.status='PENDING_OWNER_APPROVAL' and q.expires_at>p_now and q.start_at<p_end_at and q.end_at>p_start_at) then raise exception 'unavailable' using errcode='P0002';end if;select least(a.expires_at,p_start_at,p_now+make_interval(hours=>studio.booking_offer_expiry_hours)) into v_expiry from public.studio studio where studio.id=a.studio_id;if v_expiry<=p_now then raise exception 'unavailable' using errcode='P0002';end if;insert into public.free_choice_pending_request(access_id,studio_id,tattoo_case_id,artist_profile_id,selector_hash,start_at,end_at,expires_at,created_at) values(a.id,a.studio_id,a.tattoo_case_id,a.artist_profile_id,decode(p_selector,'hex'),p_start_at,p_end_at,v_expiry,p_now) returning * into r;return jsonb_build_object('start_at',r.start_at,'end_at',r.end_at,'expires_at',r.expires_at);end $$;

create function private.reject_booking_option_free_choice_conflict() returns trigger language plpgsql security definer set search_path='' as $$begin if exists(select 1 from public.free_choice_pending_request r where r.studio_id=new.studio_id and r.artist_profile_id=new.artist_profile_id and r.status='PENDING_OWNER_APPROVAL' and r.expires_at>new.created_at and r.start_at<new.end_at and r.end_at>new.start_at) then raise exception 'booking hold conflict' using errcode='23P01';end if;return new;end $$;
create trigger booking_option_free_choice_conflict before insert on public.booking_option for each row execute function private.reject_booking_option_free_choice_conflict();

create or replace function public.list_active_booking_holds(p_studio_id uuid,p_owner_user_id uuid,p_artist_profile_id uuid,p_range_start timestamptz,p_range_end timestamptz,p_now timestamptz)
returns table(start_utc timestamptz,end_utc timestamptz) language plpgsql stable security definer set search_path='' as $$begin
 if p_range_end<=p_range_start then raise exception 'invalid hold range' using errcode='22023';end if;perform private.assert_studio_owner(p_studio_id,p_owner_user_id);
 return query select x.start_at,x.end_at from (
  select o.start_at,o.end_at from public.booking_option o join public.booking_offer b on b.id=o.offer_id and b.studio_id=o.studio_id where o.studio_id=p_studio_id and o.artist_profile_id=p_artist_profile_id and ((o.status='HELD' and b.status='OPEN' and b.expires_at>p_now)or(o.status='SELECTED' and b.status='SELECTED_PENDING_CONFIRMATION' and(b.expires_at>p_now or exists(select 1 from public.booking_confirmation_operation op where op.booking_offer_id=b.id and op.studio_id=b.studio_id and op.state='INSERTING')))or(o.status='CONFIRMED' and b.status='CONFIRMED' and exists(select 1 from public.appointment ap where ap.booking_offer_id=b.id and ap.booking_option_id=o.id and ap.studio_id=b.studio_id and ap.status='CONFIRMED')))
  union all select r.start_at,r.end_at from public.free_choice_pending_request r where r.studio_id=p_studio_id and r.artist_profile_id=p_artist_profile_id and r.status='PENDING_OWNER_APPROVAL' and r.expires_at>p_now
 )x where x.start_at<p_range_end and x.end_at>p_range_start order by x.start_at;
end $$;

create or replace function public.get_public_free_choice_availability_context(p_token_hash text,p_now timestamptz) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_result jsonb;
begin
 if p_token_hash !~ '^[0-9a-f]{64}$' or p_now is null then raise exception 'invalid access' using errcode='22023';end if;
 select jsonb_build_object(
  'range_start',access.range_start,'range_end',access.range_end,'duration_minutes',access.duration_minutes,'expires_at',access.expires_at,
  'case_bound',access.tattoo_case_id is not null,'artist_display_name',artist.display_name,'time_zone',rule.time_zone,
  'slot_increment_minutes',rule.slot_increment_minutes,'buffer_before_minutes',rule.buffer_before_minutes,'buffer_after_minutes',rule.buffer_after_minutes,
  'windows',coalesce((select jsonb_agg(jsonb_build_object('weekday',availability_window.weekday,'start_time',to_char(availability_window.start_time,'HH24:MI'),'end_time',to_char(availability_window.end_time,'HH24:MI')) order by availability_window.weekday,availability_window.start_time) from public.artist_availability_window availability_window where availability_window.artist_profile_id=access.artist_profile_id and availability_window.studio_id=access.studio_id),'[]'::jsonb),
  'calendar_id',assignment.calendar_id,
  'connection',jsonb_build_object('status',connection.status,'refresh_token_ciphertext',connection.refresh_token_ciphertext,'granted_scopes',connection.granted_scopes,'credential_generation',connection.credential_generation),
  'pending_request',(select jsonb_build_object('start_at',request.start_at,'end_at',request.end_at,'expires_at',request.expires_at) from public.free_choice_pending_request request where request.access_id=access.id and request.status='PENDING_OWNER_APPROVAL' and request.expires_at>p_now),
  'holds',coalesce((select jsonb_agg(jsonb_build_object('start_at',hold.start_at,'end_at',hold.end_at)) from (
    select option.start_at,option.end_at from public.booking_option option join public.booking_offer offer on offer.id=option.offer_id and offer.studio_id=option.studio_id
    where option.studio_id=access.studio_id and option.artist_profile_id=access.artist_profile_id and ((option.status='HELD' and offer.status='OPEN' and offer.expires_at>p_now) or(option.status='SELECTED' and offer.status='SELECTED_PENDING_CONFIRMATION' and offer.expires_at>p_now)or(option.status='CONFIRMED' and offer.status='CONFIRMED'))
    union all select request.start_at,request.end_at from public.free_choice_pending_request request where request.studio_id=access.studio_id and request.artist_profile_id=access.artist_profile_id and request.status='PENDING_OWNER_APPROVAL' and request.expires_at>p_now
   ) hold where hold.start_at<access.range_end and hold.end_at>access.range_start),'[]'::jsonb)
 ) into v_result
 from public.free_choice_availability_access access
 join public.artist_profile artist on artist.id=access.artist_profile_id and artist.studio_id=access.studio_id
 join public.artist_availability_rule rule on rule.artist_profile_id=access.artist_profile_id and rule.studio_id=access.studio_id
 join public.artist_calendar_assignment assignment on assignment.artist_profile_id=access.artist_profile_id and assignment.studio_id=access.studio_id and assignment.access_role in('writer','owner')
 join public.google_calendar_connection connection on connection.id=assignment.connection_id and connection.studio_id=access.studio_id and connection.status='ACTIVE' and connection.refresh_token_ciphertext is not null and connection.granted_scopes @> array['https://www.googleapis.com/auth/calendar.events.freebusy']::text[]
 where access.token_hash=decode(p_token_hash,'hex') and access.expires_at>p_now
 and not exists(
  select 1 from public.free_choice_pending_request consumed
  where consumed.access_id=access.id and (consumed.status<>'PENDING_OWNER_APPROVAL' or consumed.expires_at<=p_now)
 );
 return v_result;
end $$;

revoke all on function public.rotate_free_choice_availability_access(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz,integer,timestamptz,timestamptz),public.get_free_choice_availability_management(uuid,uuid),public.select_public_free_choice_availability(text,text,timestamptz,timestamptz,timestamptz),private.reject_booking_option_free_choice_conflict() from public,anon,authenticated;
grant execute on function public.rotate_free_choice_availability_access(uuid,uuid,uuid,uuid,text,timestamptz,timestamptz,integer,timestamptz,timestamptz),public.get_free_choice_availability_management(uuid,uuid),public.select_public_free_choice_availability(text,text,timestamptz,timestamptz,timestamptz) to service_role;
grant execute on function public.list_active_booking_holds(uuid,uuid,uuid,timestamptz,timestamptz,timestamptz) to service_role;
